// app/api/posts/route.js — API blog trong bộ nhớ (thực tế: CSDL)
const posts = [{ id: 1, title: "Một" }, { id: 2, title: "Hai" }, { id: 3, title: "Ba" }];
let nextId = 4;

async function GET(request) {
  const sp = new URL(request.url).searchParams;
  const page = Math.max(1, Number(sp.get("page") ?? 1));
  const limit = Math.min(50, Math.max(1, Number(sp.get("limit") ?? 2)));
  const items = posts.slice((page - 1) * limit, page * limit);
  return Response.json({ page, limit, total: posts.length, items });
}

async function POST(request) {
  const body = await request.json().catch(() => null);
  if (!body || typeof body.title !== "string" || body.title.trim().length < 2) {
    return Response.json({ error: "title >= 2 ký tự" }, { status: 400 });
  }
  const post = { id: nextId++, title: body.title.trim() };
  posts.push(post);
  return Response.json(post, { status: 201 });
}

(async () => {
  const r = await GET(new Request("http://x.test/api/posts?page=2&limit=2"));
  console.log(JSON.stringify((await r.json()).items));
  const c = await POST(new Request("http://x.test/api/posts", { method: "POST", body: JSON.stringify({ title: "Bốn" }) }));
  console.log(c.status);
})();

