function paginate(items, pageStr, limitStr) {
  const toNum = (v, d) => (Number.isFinite(Number(v)) && v !== "" ? Number(v) : d);
  const page = Math.max(1, toNum(pageStr, 1));
  const limit = Math.min(50, Math.max(1, toNum(limitStr, 2)));
  return { page, limit, total: items.length, items: items.slice((page - 1) * limit, page * limit) };
}
const items = [1, 2, 3, 4, 5];
const r = paginate(items, "2", "2");
const s = paginate(items, "abc", "999");
console.log(JSON.stringify(r.items) + "|" + s.page + "," + s.limit);
